mapper.select:
SELECT id, 
FROM im_message
WHERE message_id = #{messageId}

SELECT id, 
FROM im_message
WHERE conversation_id = #{conversationId}
  AND status != 6
ORDER BY server_seq DESC
LIMIT #{offset}, #{limit}

SELECT id, 
FROM im_message
WHERE conversation_id = #{conversationId}
  AND server_seq > #{serverSeq}
  AND status != 6
ORDER BY server_seq ASC
LIMIT #{limit}

mapper.update:
UPDATE im_message
SET status = #{status}, update_time = NOW()
WHERE message_id = #{messageId}

UPDATE im_message
SET status = 3, update_time = NOW()
WHERE conversation_id = #{conversationId}
  AND receiver_id = #{receiverId}
  AND status != 3
  AND status != 5

UPDATE im_message
SET status = 5, content = '该消息已被撤回', update_time = NOW()
WHERE message_id = #{messageId}

mapper.select:
SELECT COALESCE(MAX(server_seq), 0)
FROM im_message
WHERE conversation_id = #{conversationId}
